// One audit row for the whole run — written whenever there was anything to check, including when
// every candidate turned out to be unrevivable. "Checked and could do nothing" is the steady state
// for an archived campaign and has to be on the record, not inferred from silence.
//
// Reached from two branches (the IF's false arm and Resume Campaign), so it can execute twice in one
// run — the same convergence bison-workspace-setup's Merge Outcomes uses. Harmless: it reads
// everything by node reference rather than from its input, so both executions produce the same
// object, and Record Run's ON CONFLICT (n8n_execution_id) keeps the audit to one row.
const decided = $('Decide Action').all().map((i) => i.json);
const attempted = decided.filter((d) => d.action === 'resume');

const results = $('Resume Campaign').isExecuted ? $('Resume Campaign').all().map((i) => i.json) : [];
const describe = (v) => (v == null ? null : typeof v === 'string' ? v
  : (v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })()));

const resumed = [];
const failed = [];
attempted.forEach((d, i) => {
  const r = results[i] ?? {};
  // statusCode ONLY. `status` is the vendor's word, and Number('ok') is NaN — reading it as a code
  // scores a failure as a success.
  const bad = Boolean(r.error) || Number(r.statusCode ?? 0) >= 400;
  const label = `${d.client_name} · ${d.campaign_name} (${d.queued_leads} waiting)`;
  if (bad) failed.push(`${label} — ${describe(r.message ?? r.error) ?? 'HTTP ' + r.statusCode}`);
  else resumed.push(label);
});

const cannot = decided.filter((d) => d.action === 'cannot')
  .map((d) => `${d.client_name} · ${d.campaign_name} — ${d.vendor_status}`);
const unreadable = decided.filter((d) => d.action === 'unreadable')
  .map((d) => `${d.client_name} · ${d.campaign_name} — ${d.note}`);

return [{ json: {
  checked: decided.length,
  resumed, failed, cannot, unreadable,
  already_active: decided.filter((d) => d.action === 'already_active').length,
  // integration_sync_runs.status accepts only running | success | failed, so the three-way outcome
  // has to collapse. It collapses on ONE question: did something this run ATTEMPTED get rejected?
  //
  //   failed      — a resume was refused by the vendor. We tried, it did not work.
  //   cannot      — the campaign is archived. Not a failure of this run; it is the expected steady
  //                 state for 19 of the 22 dead campaigns, and its home is the portal's OOO column.
  //   unreadable  — the campaign's status could not be read, almost always a stale api_key. Also
  //                 not caused by this run, and it has its own surface (the Workspaces column and
  //                 client_sequencers.setup_state).
  //
  // Both of the latter are recorded in the metadata and neither reddens the run. A single client
  // with a stale key would otherwise mark every run failed forever, which is how an audit trail
  // stops being able to show that something NEW went wrong.
  status: failed.length ? 'failed' : 'success',
} }];

// Classify each campaign from what the VENDOR says right now, not from our copy.
//
// Bison's own statuses, and what can be done with each:
//   active            already sending. Our row was stale; the hourly sync will catch up.
//   paused            REVIVABLE -> PATCH /campaigns/{id}/resume
//   archived          NOT revivable. There is no unarchive/restore endpoint -- probed 2026-08-20,
//                     both return 404, while /resume /pause /archive /duplicate exist. A human has
//                     to re-create the campaign in Bison; the portal's OOO column is what says so.
//   completed/draft   left alone. A draft has no sequence and resuming it would send nothing; a
//                     completed campaign has run its course.
const REVIVABLE = ['paused'];

const rows = $('Select Routed OOO Campaigns').all().map((i) => i.json);
const out = [];

$input.all().forEach((item, i) => {
  const row = rows[i] ?? {};
  const body = item.json ?? {};
  // n8n reports a node error as { message, error } and error is an object; String(err) would give
  // "[object Object]", which says nothing.
  const describe = (v) => (v == null ? null : typeof v === 'string' ? v
    : (v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })()));

  if (body.error || Number(body.statusCode ?? 0) >= 400) {
    out.push({ json: { ...row, vendor_status: null, action: 'unreadable',
                       note: describe(body.message ?? body.error) ?? `HTTP ${body.statusCode}` } });
    return;
  }
  const c = body.data ?? body;
  const vendor = String(c?.status ?? '').trim() || 'unknown';
  const action = vendor === 'active' ? 'already_active'
    : REVIVABLE.includes(vendor) ? 'resume'
    : 'cannot';
  out.push({ json: {
    ...row,
    vendor_status: vendor,
    // Carried so the audit row can say how big the release was. Resuming a campaign mails everyone
    // who piled up inside it, at once: on 2026-08-20 UniTalk's `male` held 150 waiting contacts.
    queued_leads: Number(c?.total_leads ?? 0) - Number(c?.total_leads_contacted ?? 0),
    action,
    note: action === 'cannot' ? `vendor status ${vendor} — no API can revive this; re-create it in Bison` : null,
  } });
});

return out;
